using System;using System.IO;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using SolidWorks.Interop.sldworks;
public static class GripperValidate {
 static ISldWorks sw; static JavaScriptSerializer ser=new JavaScriptSerializer();
 static Dictionary<string,object> O(params object[] p){var r=new Dictionary<string,object>();for(int i=0;i<p.Length;i+=2)r[(string)p[i]]=p[i+1];return r;}
 static IModelDoc2 Open(string path){int e=0,w=0;var d=(IModelDoc2)sw.GetOpenDocumentByName(path);if(d==null)d=(IModelDoc2)sw.OpenDoc6(path,path.EndsWith("SLDASM",StringComparison.OrdinalIgnoreCase)?2:1,3,"",ref e,ref w);if(d==null)throw new Exception("Open failed "+path+" "+e);return d;}
 public static void Parts(string root){sw=(ISldWorks)Marshal.GetActiveObject("SldWorks.Application");ser.MaxJsonLength=int.MaxValue;var data=(Dictionary<string,object>)ser.DeserializeObject(File.ReadAllText(Path.Combine(root,"inputs","assembly_original.json")));var results=new List<object>();var seen=new HashSet<string>();foreach(Dictionary<string,object> co in (object[])data["components"]){string old=(string)co["path"],fn=Path.GetFileName(old);if(!fn.StartsWith("14AK-")||!seen.Add(fn))continue;var a=Open(old);var d=Open(Path.Combine(root,"models","P"+fn.Substring(5)));d.ForceRebuild3(false);var bs=(object[])((IPartDoc)d).GetBodies2(0,false);var os=(object[])((IPartDoc)a).GetBodies2(0,false);double av=((IMassProperty)a.Extension.CreateMassProperty()).Volume,bv=((IMassProperty)d.Extension.CreateMassProperty()).Volume,common=0;int be=0,faults=0;foreach(IBody2 b in bs)faults+=b.Check2();var x=(IBody2)((IBody2)os[0]).Copy();var y=(IBody2)((IBody2)bs[0]).Copy();var intersection=x.Operations2(15901,y,out be) as object[];if(intersection!=null)foreach(IBody2 b in intersection)common+=((double[])b.GetMassProperties(1))[3];var errors=new List<object>();var sketches=new List<object>();for(var f=(IFeature)d.FirstFeature();f!=null;f=(IFeature)f.GetNextFeature()){if(f.GetErrorCode()!=0)errors.Add(O("feature",f.Name,"code",f.GetErrorCode()));if(f.GetTypeName2()=="ProfileFeature")sketches.Add(O("name",f.Name,"constraint_status",((ISketch)f.GetSpecificFeature2()).GetConstrainedStatus()));}double diff=Math.Max(0,(av+bv-2*common)*1e9);bool pass=bs.Length==1&&faults==0&&be==0&&intersection!=null&&diff<=.001&&errors.Count==0;results.Add(O("part",fn,"solid_count",bs.Length,"body_check",faults,"source_volume_mm3",av*1e9,"built_volume_mm3",bv*1e9,"symmetric_difference_mm3",diff,"boolean_status",be,"feature_errors",errors,"sketches",sketches,"pass",pass));Console.WriteLine(fn+" PASS="+pass+" symmetric_difference_mm3="+diff+" errors="+errors.Count);sw.CloseDoc(d.GetTitle());}
 File.WriteAllText(Path.Combine(root,"checks","part_validation.json"),ser.Serialize(results));}
}
